/* My Finance Records V12.19.0 · lazy Supabase browser loader.
   Cloud sync requires internet, so the official Supabase v2 ESM build is loaded only when configured. */
window.financeLoadSupabase = window.financeLoadSupabase || (async function financeLoadSupabase() {
  if (window.supabase && typeof window.supabase.createClient === "function") return window.supabase;
  if (!window.__financeSupabasePromise) {
    window.__financeSupabasePromise = import("https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm");
  }
  return window.__financeSupabasePromise;
});
